) VALUES (
    '4765643b-dfa3-fbcf-03a0-7b656d651fe0',
    'a87ec42b-5391-6d45-7e28-0c5603531725',
    'NGUYỄN THỊ VƯƠNG HOÀN',
    NULL,
    NULL,
    1980,
    'OTHER',
